import { describe, it } from "vitest";

describe("MHPCO claim office", () => {
  it.todo("quotes an empty item list for a newcomer -- premium 5 G (fee only)");
  it.todo("quotes a plain sword for a newcomer's first contract -- 100 + 10 first insurance + 5 fee = 115 G");
  it.todo("quotes a plain amulet for a newcomer -- 60 + 6 + 5 = 71 G");
  it.todo("quotes a plain staff for a newcomer -- 80 + 8 + 5 = 93 G");
  it.todo("quotes a plain potion for a newcomer -- 40 + 4 + 5 = 49 G");
  it.todo("quotes 2 runes -- base 50 G -> 55 + 5 = 60 G");
  it.todo("quotes 3 runes as a block -- base 60 G -> 66 + 5 = 71 G");
  it.todo("quotes 4 runes without block (block requires exactly 3) -- base 100 G -> 115 G");
  it.todo("quotes 7 runes -- base 175 G -> 197.5 G rounded up in MHPCO's favor to 198 G");
  it.todo("quotes 2 runes + 1 moonstone without block (different types) -- base 75 G -> 87.5 rounded up to 88 G");
  it.todo("quotes a cursed steel sword (enchantment 3) for a newcomer -- 100 + 50 + 10 + 5 = 165 G");
  it.todo("applies the curse surcharge only to the cursed item: cursed sword + plain amulet -- 160 + 50 + 16 + 5 = 231 G");
  it.todo("adds the high-enchantment surcharge at exactly enchantment 5 -- 100 + 30 + 10 + 5 = 145 G");
  it.todo("gives the loyalty discount at exactly 2 years -- sword 100 - 20 + 10 + 5 = 95 G");
  it.todo("gives the follow-up discount on the second quote of the scenario -- sword quotes 115 G then 100 G");
  it.todo("claims standard reimbursement for a steel sword (enchantment 3), damage 500 -- payout 400 G, remainingCap 1600 G");
  it.todo("claims damage 200 on an insured rune (value 250) -- payout 100 G, remainingCap 400 G");
  it.todo("runs the schema example: 5-year customer amulet quote 59 G, claim 200 -- payout 100 G, remainingCap 1100 G");
  it.todo("claims damage 300 on an insured staff (value 800) -- payout 200 G, remainingCap 1400 G");
  it.todo("claims damage 300 on an insured potion (value 400) -- payout 200 G, remainingCap 600 G");
  it.todo("claims damage 200 on an insured moonstone (value 250) -- payout 100 G, remainingCap 400 G");
  it.todo("applies the deductible per damaged item: sword 500 + amulet 300 -- payout 600 G, remainingCap 2600 G");
  it.todo("reimburses 50 % for enchantment >= 8: steel sword enchantment 9, damage 1000 -- payout 400 G");
  it.todo("rounds payouts down in MHPCO's favor: enchantment 9 sword, damage 901 -> 350.5 -- payout 350 G");
  it.todo("caps payouts at twice the insurance sum: two claims of 1500 on a sword -- 1400/600 then 600/0");
  it.todo("rejects a claim with more sword damages than insured swords -- runScenario throws an Error");
  it.todo("rejects a claim with a negative damage amount (-200) -- runScenario throws an Error");
  it.todo("rejects a quote with an unknown item type (broomstick) -- runScenario throws an Error");
  it.todo("CLI reads the schema example from stdin and writes results JSON to stdout");
  it.todo("CLI exits non-zero, writes stderr and no results for an unknown quote item type");

  describe("verification", () => {
    it.todo("quotes 3 runes + 3 moonstones as two separate blocks -- base 120 G -> 137 G");
    it.todo("stacks curse and high enchantment at exactly enchantment 5 -- 100 + 50 + 30 + 10 + 5 = 195 G");
    it.todo("adds no high-enchantment surcharge at enchantment 4 -- 115 G");
    it.todo("adds only the curse surcharge to a cursed sword with enchantment 4 -- 165 G");
    it.todo("integration: 3-year customer's second quote, cursed steel sword enchantment 7 -- 160 G");
    it.todo("dragon-material sword enchantment 5, damage 800 -- payout 700 G (full reimbursement)");
    it.todo("dragon-material sword enchantment 9, damage 1000 -- payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword exactly enchantment 8, damage 1000 -- payout 400 G");
    it.todo("rejects an amulet damage when only a sword is insured -- runScenario throws an Error");
    it.todo("rejects a damage with an unknown item type -- runScenario throws an Error");
    it.todo("two swords: insurance sum 2000, cap 4000; damages 500 and 300 each with deductible -- payout 600, remainingCap 3400");
    it.todo("sword + amulet: cap 3200; sword damage 500 -- payout 400, remainingCap 2800");
    it.todo("cursed sword cap stays 2000 (unmodified value); damage 500 -- payout 400, remainingCap 1600");
    it.todo("sword + 3 runes block: insurance sum 1750, cap 3500; sword damage 500 -- payout 400, remainingCap 3100");
    it.todo("keeps intermediate fractions: two enchantment-9 swords, damages 901 + 901 -- payout 701, remainingCap 3299");
    it.todo("CLI exits non-zero with stderr when a damaged item is not part of the policy");
    it.todo("CLI exits non-zero with stderr for a negative damage amount");
  });
});

