import type { QuoteItem } from "./premium.js";
import { INSURANCE_VALUES } from "./priceList.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const CAP_FACTOR = 2;
const DEDUCTIBLE = 100;

function insuranceSum(insuredItems: QuoteItem[]): number {
  return insuredItems.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
}

export function claim(insuredItems: QuoteItem[], damages: Damage[]): ClaimResult {
  const cap = CAP_FACTOR * insuranceSum(insuredItems);
  const payout = damages.reduce((sum, damage) => sum + damage.amount - DEDUCTIBLE, 0);
  return { payout, remainingCap: cap - payout };
}
