import { claim, openPolicy, type ClaimResult, type Policy, type Damage } from "./claim.js";
import { premium, type Customer, type QuoteItem } from "./premium.js";

export type { ClaimResult, Customer, Damage, QuoteItem };

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export type StepResult = QuoteResult | ClaimResult;

function hasEarlierContract(steps: Step[], index: number): boolean {
  return steps.slice(0, index).some((step) => step.op === "quote");
}

export function runScenario(scenario: Scenario): StepResult[] {
  const policies = new Map<number, Policy>();
  return scenario.steps.map((step, index) => {
    if (step.op === "quote") {
      policies.set(index, openPolicy(step.items));
      return { premium: premium(scenario.customer, step.items, hasEarlierContract(scenario.steps, index)) };
    }
    return claim(policies.get(step.policy) as Policy, step.incident.damages);
  });
}
import { isComponent, mainItemBasePremium, BLOCK_BASE_PREMIUM, BLOCK_SIZE, COMPONENT_BASE_PREMIUM, COMPONENT_TYPES } from "./priceList.js";

export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT_PERCENT = 20;
const FOLLOW_UP_DISCOUNT_PERCENT = 15;
const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const PERCENT = 100;

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / PERCENT;
}

function alikeComponentsBasePremium(count: number): number {
  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
}

function componentsBasePremium(items: QuoteItem[]): number {
  return COMPONENT_TYPES.reduce(
    (sum, type) => sum + alikeComponentsBasePremium(items.filter((item) => item.type === type).length),
    0,
  );
}

function mainItemsOf(items: QuoteItem[]): QuoteItem[] {
  return items.filter((item) => !isComponent(item.type));
}

function policyBasePremium(items: QuoteItem[]): number {
  return mainItemsOf(items).reduce((sum, item) => sum + mainItemBasePremium(item.type), 0) + componentsBasePremium(items);
}

function isHighlyEnchanted(item: QuoteItem): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
}

function itemRiskSurcharge(item: QuoteItem): number {
  const cursePercent = item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
  const enchantmentPercent = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
  return percentOf(mainItemBasePremium(item.type), cursePercent + enchantmentPercent);
}

function policyModifierPercent(customer: Customer, isFollowUpContract: boolean): number {
  const loyaltyPercent = customer.yearsWithMHPCO >= LOYALTY_YEARS ? LOYALTY_DISCOUNT_PERCENT : 0;
  const followUpPercent = isFollowUpContract ? FOLLOW_UP_DISCOUNT_PERCENT : 0;
  return FIRST_INSURANCE_SURCHARGE_PERCENT - loyaltyPercent - followUpPercent;
}

export function premium(customer: Customer, items: QuoteItem[], isFollowUpContract: boolean): number {
  const basePremium = policyBasePremium(items);
  const riskSurcharges = mainItemsOf(items).reduce((sum, item) => sum + itemRiskSurcharge(item), 0);
  const policyModifiers = percentOf(basePremium, policyModifierPercent(customer, isFollowUpContract));
  return Math.ceil(basePremium + riskSurcharges + policyModifiers + PROCESSING_FEE);
}
interface MainItemPrice {
  insuranceValue: number;
  basePremium: number;
}

const MAIN_ITEMS: Record<string, MainItemPrice> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
};

export const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_INSURANCE_VALUE = 250;
export const COMPONENT_BASE_PREMIUM = 25;
export const BLOCK_SIZE = 3;
export const BLOCK_BASE_PREMIUM = 60;

export function assertKnownItemType(type: string): void {
  if (!isComponent(type) && !(type in MAIN_ITEMS)) {
    throw new Error(`Unknown item type: ${type}`);
  }
}

export function isComponent(type: string): boolean {
  return COMPONENT_TYPES.includes(type);
}

export function mainItemBasePremium(type: string): number {
  return MAIN_ITEMS[type].basePremium;
}

export function insuranceValue(type: string): number {
  return isComponent(type) ? COMPONENT_INSURANCE_VALUE : MAIN_ITEMS[type].insuranceValue;
}
